WITH base AS (SELECT * FROM departments WHERE location = 'Tokyo'), agg AS (SELECT CASE WHEN dept_name IN ('Sales', 'Engineering') THEN 'group_a' ELSE 'other' END AS dept_name_group, CASE WHEN budget >= 4255000 THEN 'high' WHEN budget >= 1174000 THEN 'mid' ELSE 'low' END AS budget_bucket, ROUND(STDDEV(budget), 2) AS stddev_budget FROM base GROUP BY CASE WHEN dept_name IN ('Sales', 'Engineering') THEN 'group_a' ELSE 'other' END, CASE WHEN budget >= 4255000 THEN 'high' WHEN budget >= 1174000 THEN 'mid' ELSE 'low' END) SELECT dept_name_group, stddev_budget FROM agg ORDER BY dept_name_group ASC
